// src/index.js
import "./App.scss";
import "./Button.scss";
import "./Responsive1500.scss";
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { worker } from "./mocks/browser";
import { FRONT_BASE } from "./api/config";

(async function bootstrap() {
  const base = (FRONT_BASE || "/").replace(/\/+$/, "");
  const host =
    typeof window !== "undefined" && window.location
      ? window.location.hostname
      : "";

  // 로컬에서는 /, 배포에선 /woodenpages/
  const isLocal = /^(localhost|127\.0\.0\.1|0\.0\.0\.0)$/.test(host);
  const swUrl = isLocal ? "/mockServiceWorker.js" : `${base}/mockServiceWorker.js`;
  const swScope = isLocal ? "/" : `${base}/`;

  // 1) SW 지원 안 하면 그냥 렌더
  const canSW = typeof navigator !== "undefined" && "serviceWorker" in navigator;

  try {
    if (canSW) {
      // 2) 등록이 2초 넘게 걸리면 포기하고 통과
      await Promise.race([
        worker.start({
          serviceWorker: { url: swUrl, options: { scope: swScope } },
          onUnhandledRequest: "warn",
        }),
        new Promise((_, rej) => setTimeout(() => rej(new Error("msw-timeout")), 2000)),
      ]);
      console.log("[MSW] registered:", { url: swUrl, scope: swScope });
    } else {
      console.warn("[MSW] ServiceWorker not supported. Running without mocks.");
    }
  } catch (e) {
    console.warn("[MSW] start failed. Running without mocks:", e?.message || e);
  } finally {
    // 3) 성공/실패와 상관없이 앱은 반드시 렌더
    const root = ReactDOM.createRoot(document.getElementById("root"));
    root.render(
      <React.StrictMode>
        <App />
      </React.StrictMode>
    );
  }
})();
